[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$ExportDirectory)
$ErrorActionPreference = 'Stop'
$directory = (Resolve-Path -LiteralPath $ExportDirectory).Path
$source = Join-Path $directory 'runtime-map.json'
if (-not (Test-Path -LiteralPath $source)) { throw 'Export a bounded sector with --runtime-json first.' }
$data = [System.IO.File]::ReadAllText($source).Replace('<', '\u003c')
$template = @'
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ETSADS · 地图校验</title><style>
:root{color-scheme:dark;font:15px system-ui,sans-serif;background:#0c1420;color:#dce6f1}*{box-sizing:border-box}body{margin:0}header{display:flex;align-items:center;gap:18px;padding:18px 24px;border-bottom:1px solid #27384b}h1{font-size:18px;margin:0;font-weight:650}small{color:#91a8be}.badge{background:#503d18;color:#ffd684;border-radius:6px;padding:6px 10px;margin-left:auto}main{display:grid;grid-template-columns:1fr 300px;height:calc(100vh - 72px)}canvas{display:block;width:100%;height:100%;touch-action:none;background:#101c2b}aside{padding:22px;border-left:1px solid #27384b;overflow:auto}button{background:#1c344d;color:#dfedfa;border:1px solid #46627e;border-radius:8px;padding:9px 14px;cursor:pointer}button:focus-visible{outline:2px solid #67d9dc}p{line-height:1.6}label{display:block;margin:12px 0}code{word-break:break-all;font-size:12px}.muted{color:#91a8be}.road{color:#68d1df}.prefab{color:#c1a3ff}#detail{font-size:13px;line-height:1.7} @media(max-width:700px){main{grid-template-columns:1fr}aside{height:220px}canvas{height:60vh}.badge{font-size:11px}small{display:none}}
</style><header><h1>ETSADS · 地图校验</h1><small>本机游戏归档 · ENU / 米</small><span class="badge">尚未通过驾驶验收</span></header>
<main><canvas id="map" aria-label="真实游戏车道图，可拖动平移、滚轮缩放"></canvas><aside><button id="fit">适应视图</button><p id="count"></p><label class="road"><input id="road" type="checkbox" checked> 道路车道</label><label class="prefab"><input id="prefab" type="checkbox" checked> 路口导航曲线</label><p class="muted">拖动平移，滚轮缩放。移动鼠标查看车道来源和连接。</p><div id="detail">将鼠标移到车道附近。</div><p class="muted">道路宽度和限速未确认。该视图用于开发核验，不代表已验证可安全自动驾驶。</p></aside></main>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent),lanes=data.lanes,canvas=document.getElementById('map'),ctx=canvas.getContext('2d'),detail=document.getElementById('detail');let scale=1,cx=0,cy=0,drag=null,hover=null;
const all=lanes.flatMap(l=>l.center),bounds=all.reduce((b,p)=>[Math.min(b[0],p.x),Math.min(b[1],p.y),Math.max(b[2],p.x),Math.max(b[3],p.y)],[Infinity,Infinity,-Infinity,-Infinity]);
document.getElementById('count').textContent=lanes.length.toLocaleString()+' 条真实车道 · '+all.length.toLocaleString()+' 个采样点';
function fit(){cx=(bounds[0]+bounds[2])/2;cy=(bounds[1]+bounds[3])/2;scale=Math.min(canvas.clientWidth/(bounds[2]-bounds[0]+60),canvas.clientHeight/(bounds[3]-bounds[1]+60));draw()}
function screen(p){return[(p.x-cx)*scale+canvas.clientWidth/2,canvas.clientHeight/2-(p.y-cy)*scale]}
function draw(){const dpr=devicePixelRatio||1;canvas.width=canvas.clientWidth*dpr;canvas.height=canvas.clientHeight*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);for(const l of lanes){const road=l.id.includes(':road:');if(!document.getElementById(road?'road':'prefab').checked)continue;ctx.beginPath();l.center.forEach((p,i)=>{const [x,y]=screen(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=l===hover?'#fff':road?'#68d1df':'#c1a3ff';ctx.lineWidth=l===hover?3:1.1;ctx.stroke()}ctx.fillStyle='#91a8be';ctx.fillText('东 →  北 ↑  |  '+(1/scale).toFixed(1)+' m/px',18,canvas.clientHeight-18)}
canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY,cx,cy];canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointermove',e=>{if(drag){cx=drag[2]-(e.clientX-drag[0])/scale;cy=drag[3]+(e.clientY-drag[1])/scale;draw();return}const r=canvas.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;let best=100,candidate=null;for(const l of lanes)for(const p of l.center){const [x,y]=screen(p),d=(x-mx)**2+(y-my)**2;if(d<best){best=d;candidate=l}}hover=candidate;if(candidate){detail.replaceChildren();const title=document.createElement('code');title.textContent=candidate.id;detail.append(title);const text=document.createElement('p');text.textContent='来源：'+candidate.geometry_status+'；后继 '+candidate.successors.length+'；前驱 '+candidate.predecessors.length+'；宽度/限速：待确认';detail.append(text)}draw()});canvas.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.002,Math.min(100,scale*Math.exp(-e.deltaY*.001)));draw()},{passive:false});document.getElementById('fit').onclick=fit;for(const id of ['road','prefab'])document.getElementById(id).onchange=draw;new ResizeObserver(draw).observe(canvas);fit();
</script></html>
'@
[System.IO.File]::WriteAllText((Join-Path $directory 'preview.html'), $template.Replace('__DATA__', $data), [System.Text.UTF8Encoding]::new($false))
Write-Output (Join-Path $directory 'preview.html')
